5	/**
6	 * Derives the {@code locality} (canonical region) from an owner's postcode, falling back
7	 * to a fixed city-to-region table when the postcode is absent or in no known range.
8	 * Cities not in the table resolve to {@code UNKNOWN}.
9	 */
10	public final class Locality {
11	
12	    private static final Map<String, String> CITY_REGION =
13	            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
14	
15	    private static final Map<String, int[]> REGION_RANGE = Map.of(
16	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
17	
18	    private Locality() {
19	    }
20	
21	    public static String of(String city) {
22	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
23	    }
24	
25	    public static String of(String city, String postcode) {
26	        String region = regionForPostcode(postcode);
27	        return region != null ? region : of(city);
28	    }
29	
30	    private static String regionForPostcode(String postcode) {
31	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
32	            return null;
33	        }
34	        int value = Integer.parseInt(postcode);
35	        for (Map.Entry<String, int[]> range : REGION_RANGE.entrySet()) {
36	            if (value >= range.getValue()[0] && value <= range.getValue()[1]) {
37	                return range.getKey();
38	            }
39	        }
40	        return null;
41	    }
42	}
