3	/**
4	 * Derives the numeric {@code membershipLevel} (1-3) assigned on creation: starts at 1,
5	 * adds 1 when an email address is present, adds 1 when namesakeCount is 0, capped at 3
6	 * (level 4 is reserved for tenure).
7	 */
8	public final class MembershipTier {
9	
10	    private MembershipTier() {
11	    }
12	
13	    public static int of(Integer namesakeCount, String email) {
14	        int level = 1;
15	        if (email != null && !email.isBlank()) {
16	            level++;
17	        }
18	        if (namesakeCount != null && namesakeCount == 0) {
19	            level++;
20	        }
21	        return Math.min(level, 3);
22	    }
23	}
