3	/**
4	 * Derives the single duplicate-detection key that consolidates the former separate
5	 * telephone, email and household checks: {@code normalizedTelephone|email|householdId},
6	 * with an empty segment for an absent email. Telephone is already E.164-normalised and
7	 * email lower-cased by earlier steps, and {@link HouseholdId} normalises lastName/address,
8	 * so two owners collide only when their whole key matches.
9	 */
10	public final class IdentityKey {
11	
12	    private IdentityKey() {
13	    }
14	
15	    public static String of(String telephone, String email, String lastName, String address) {
16	        return blankToEmpty(telephone) + '|' + blankToEmpty(email) + '|'
17	                + HouseholdId.of(lastName, address);
18	    }
19	
20	    private static String blankToEmpty(String value) {
21	        return value == null ? "" : value;
22	    }
23	}
