3	/**
4	 * Derives the stable {@code householdId} shared by owners with the same lastName and
5	 * address. Names and addresses are compared case-insensitively with collapsed whitespace,
6	 * matching {@link RequireUniqueHousehold}, so co-resident same-lastName owners always
7	 * resolve to one identifier.
8	 */
9	public final class HouseholdId {
10	
11	    private HouseholdId() {
12	    }
13	
14	    public static String of(String lastName, String address) {
15	        String key = normalise(lastName) + '|' + normalise(address);
16	        return "H-" + Integer.toHexString(key.hashCode());
17	    }
18	
19	    private static String normalise(String value) {
20	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
21	    }
22	}
