3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Rolls a registration date onto a business day: a Saturday or Sunday moves forward to the
8	 * following Monday, any weekday is returned unchanged.
9	 */
10	public final class BusinessDay {
11	
12	    private BusinessDay() {
13	    }
14	
15	    public static LocalDate roll(LocalDate date) {
16	        DayOfWeek day = date.getDayOfWeek();
17	        if (day == DayOfWeek.SATURDAY) {
18	            return date.plusDays(2);
19	        }
20	        if (day == DayOfWeek.SUNDAY) {
21	            return date.plusDays(1);
22	        }
23	        return date;
24	    }
25	}
